ARCHITECTURE rtl OF Subsystem1 IS

  -- Component Declarations
  COMPONENT Subsystem1_tc
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          clk_enable                      :   IN    std_logic;
          enb_1_25_0                      :   OUT   std_logic;
          enb_1_25_1                      :   OUT   std_logic;
          enb_1_51200_0                   :   OUT   std_logic
          );
  END COMPONENT;

  COMPONENT FFT
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          dataIn                          :   IN    std_logic_vector(11 DOWNTO 0);  -- sfix12_En11
          validIn                         :   IN    std_logic;
          syncReset                       :   IN    std_logic;
          dataOut_re                      :   OUT   std_logic_vector(22 DOWNTO 0);  -- sfix23_En11
          dataOut_im                      :   OUT   std_logic_vector(22 DOWNTO 0);  -- sfix23_En11
          validOut                        :   OUT   std_logic
          );
  END COMPONENT;

  COMPONENT S_R_Flip_Flop_block2
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          in1                             :   IN    std_logic;
          in2                             :   IN    std_logic;
          out1                            :   OUT   std_logic
          );
  END COMPONENT;

  COMPONENT Sample_and_Hold_block2
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          In_re                           :   IN    vector_of_std_logic_vector12(0 TO 2047);  -- sfix12_En11 [2048]
          In_im                           :   IN    vector_of_std_logic_vector12(0 TO 2047);  -- sfix12_En11 [2048]
          Trigger                         :   IN    std_logic;
          alpha_re                        :   OUT   vector_of_std_logic_vector12(0 TO 2047);  -- sfix12_En11 [2048]
          alpha_im                        :   OUT   vector_of_std_logic_vector12(0 TO 2047)  -- sfix12_En11 [2048]
          );
  END COMPONENT;

  COMPONENT BUF_MIN_MAX_AVG
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          enb_1_51200_0                   :   IN    std_logic;
          data                            :   IN    std_logic_vector(11 DOWNTO 0);  -- sfix12_En11
          validIn                         :   IN    std_logic;
          reset_1                         :   IN    std_logic;
          Buffer_rsvd                     :   OUT   vector_of_std_logic_vector12(0 TO 2047);  -- sfix12_En11 [2048]
          Max                             :   OUT   std_logic_vector(15 DOWNTO 0);  -- ufix16_En16
          Min                             :   OUT   std_logic_vector(15 DOWNTO 0);  -- sfix16_En15
          ValidOut                        :   OUT   std_logic
          );
  END COMPONENT;

  COMPONENT Subsystem_Reference
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          FFT_In_re                       :   IN    std_logic_vector(11 DOWNTO 0);  -- sfix12_En11
          FFT_In_im                       :   IN    std_logic_vector(11 DOWNTO 0);  -- sfix12_En11
          Valid_In                        :   IN    std_logic;
          reset_1                         :   IN    std_logic;
          THD                             :   OUT   std_logic_vector(15 DOWNTO 0);  -- sfix16_En15
          valid_out                       :   OUT   std_logic
          );
  END COMPONENT;

  COMPONENT myRMS
    PORT( clk                             :   IN    std_logic;
          reset                           :   IN    std_logic;
          enb_1_25_0                      :   IN    std_logic;
          data                            :   IN    std_logic_vector(11 DOWNTO 0);  -- sfix12_En11
          validIn                         :   IN    std_logic;
          reset_1                         :   IN    std_logic;
          y                               :   OUT   std_logic_vector(15 DOWNTO 0);  -- ufix16_En7
          validOut                        :   OUT   std_logic
          );
  END COMPONENT;

  -- Component Configuration Statements
  FOR ALL : Subsystem1_tc
    USE ENTITY work.Subsystem1_tc(rtl);

  FOR ALL : FFT
    USE ENTITY work.FFT(rtl);

  FOR ALL : S_R_Flip_Flop_block2
    USE ENTITY work.S_R_Flip_Flop_block2(rtl);

  FOR ALL : Sample_and_Hold_block2
    USE ENTITY work.Sample_and_Hold_block2(rtl);

  FOR ALL : BUF_MIN_MAX_AVG
    USE ENTITY work.BUF_MIN_MAX_AVG(rtl);

  FOR ALL : Subsystem_Reference
    USE ENTITY work.Subsystem_Reference(rtl);

  FOR ALL : myRMS
    USE ENTITY work.myRMS(rtl);

  -- Signals
  SIGNAL enb_1_25_0                       : std_logic;
  SIGNAL enb_1_51200_0                    : std_logic;
  SIGNAL enb_1_25_1                       : std_logic;
  SIGNAL Buffer_rsvd_1                    : std_logic;
  SIGNAL FFT_out1_re                      : std_logic_vector(22 DOWNTO 0);  -- ufix23
  SIGNAL FFT_out1_im                      : std_logic_vector(22 DOWNTO 0);  -- ufix23
  SIGNAL FFT_out2                         : std_logic;
  SIGNAL Deserializer1D_contl_cnt         : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_contl_cntGlobal   : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_contl_cntInnerRegCtrol : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_contl_cnt_next    : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_contl_cntGlobal_next : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_contl_cntInnerRegCtrol_next : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL Deserializer1D_innerRegEn        : std_logic;
  SIGNAL Deserializer1D_innerRegCtrolEn   : std_logic;
  SIGNAL Deserializer1D_outBypassEn       : std_logic;
  SIGNAL Deserializer1D_tapDelayEn        : std_logic;
  SIGNAL Deserializer1D_hOutSignalsContl  : std_logic;
  SIGNAL Deserializer1D_tapDelayEn_1      : std_logic;
  SIGNAL FFT_out1_re_signed               : signed(22 DOWNTO 0);  -- sfix23_En11
  SIGNAL FFT_out1_im_signed               : signed(22 DOWNTO 0);  -- sfix23_En11
  SIGNAL Bit_Shift_out1_re                : signed(22 DOWNTO 0);  -- sfix23_En11
  SIGNAL Bit_Shift_out1_im                : signed(22 DOWNTO 0);  -- sfix23_En11
  SIGNAL Data_Type_Conversion_out1_re     : signed(11 DOWNTO 0);  -- sfix12_En11
  SIGNAL Data_Type_Conversion_out1_im     : signed(11 DOWNTO 0);  -- sfix12_En11
  SIGNAL Deserializer1D_tapout_re         : vector_of_signed12(0 TO 2046);  -- sfix12_En11 [2047]
  SIGNAL Deserializer1D_tapout_im         : vector_of_signed12(0 TO 2046);  -- sfix12_En11 [2047]
  SIGNAL Deserializer1D_muxOut_re         : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Deserializer1D_muxOut_im         : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Deserializer1D_deserInnerOut_re  : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Deserializer1D_deserInnerOut_im  : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Deserializer1D_OutRegComp_reg_re : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Deserializer1D_OutRegComp_reg_im : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL deserializer_PostProcessed_re    : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL deserializer_PostProcessed_im    : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL deserializer_PostProcessed_re_1  : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL deserializer_PostProcessed_im_1  : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Rate_Transition_out1_re          : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Rate_Transition_out1_im          : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL Rate_Transition_out1_re_1        : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL Rate_Transition_out1_im_1        : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL Deserializer1D_deserInnerOut     : std_logic;
  SIGNAL Deserializer1D_OutRegComp_reg    : std_logic;  -- ufix1
  SIGNAL Deserializer1D_out2              : std_logic;
  SIGNAL Deserializer1D_out2_1            : std_logic;
  SIGNAL S_R_Flip_Flop_out1               : std_logic;
  SIGNAL Sample_and_Hold_out1_re          : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL Sample_and_Hold_out1_im          : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL BUF_MIN_MAX_AVG_out1             : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL BUF_MIN_MAX_AVG_out2             : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL BUF_MIN_MAX_AVG_out3             : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL BUF_MIN_MAX_AVG_out4             : std_logic;
  SIGNAL Subsystem_Reference_out1         : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL Subsystem_Reference_out2         : std_logic;
  SIGNAL myRMS_out1                       : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL myRMS_out2                       : std_logic;
  SIGNAL OR_out1                          : std_logic;
  SIGNAL Buffer_signed                    : signed(11 DOWNTO 0);  -- sfix12_En11

BEGIN
  -- Divide by FFT length shift

  u_Subsystem1_tc : Subsystem1_tc
    PORT MAP( clk => clk,
              reset => reset,
              clk_enable => clk_enable,
              enb_1_25_0 => enb_1_25_0,
              enb_1_25_1 => enb_1_25_1,
              enb_1_51200_0 => enb_1_51200_0
              );

  u_FFT : FFT
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              dataIn => Buffer_rsvd,  -- sfix12_En11
              validIn => Buffer_rsvd_1,
              syncReset => reset_1,
              dataOut_re => FFT_out1_re,  -- sfix23_En11
              dataOut_im => FFT_out1_im,  -- sfix23_En11
              validOut => FFT_out2
              );

  u_S_R_Flip_Flop_inst : S_R_Flip_Flop_block2
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              in1 => Deserializer1D_out2_1,
              in2 => reset_1,
              out1 => S_R_Flip_Flop_out1
              );

  u_Sample_and_Hold : Sample_and_Hold_block2
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              In_re => Rate_Transition_out1_re_1,  -- sfix12_En11 [2048]
              In_im => Rate_Transition_out1_im_1,  -- sfix12_En11 [2048]
              Trigger => S_R_Flip_Flop_out1,
              alpha_re => Sample_and_Hold_out1_re,  -- sfix12_En11 [2048]
              alpha_im => Sample_and_Hold_out1_im  -- sfix12_En11 [2048]
              );

  u_BUF_MIN_MAX_AVG : BUF_MIN_MAX_AVG
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              enb_1_51200_0 => enb_1_51200_0,
              data => Buffer_rsvd,  -- sfix12_En11
              validIn => Buffer_rsvd_1,
              reset_1 => reset_1,
              Buffer_rsvd => BUF_MIN_MAX_AVG_out1,  -- sfix12_En11 [2048]
              Max => BUF_MIN_MAX_AVG_out2,  -- ufix16_En16
              Min => BUF_MIN_MAX_AVG_out3,  -- sfix16_En15
              ValidOut => BUF_MIN_MAX_AVG_out4
              );

  u_Subsystem_Reference : Subsystem_Reference
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              FFT_In_re => std_logic_vector(Data_Type_Conversion_out1_re),  -- sfix12_En11
              FFT_In_im => std_logic_vector(Data_Type_Conversion_out1_im),  -- sfix12_En11
              Valid_In => FFT_out2,
              reset_1 => reset_1,
              THD => Subsystem_Reference_out1,  -- sfix16_En15
              valid_out => Subsystem_Reference_out2
              );

  u_myRMS : myRMS
    PORT MAP( clk => clk,
              reset => reset,
              enb_1_25_0 => enb_1_25_0,
              data => Buffer_rsvd,  -- sfix12_En11
              validIn => Buffer_rsvd_1,
              reset_1 => reset_1,
              y => myRMS_out1,  -- ufix16_En7
              validOut => myRMS_out2
              );

  Buffer_rsvd_1 <= data_valid;

  Deserializer1D_contl_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_contl_cnt <= to_unsigned(16#000#, 12);
      Deserializer1D_contl_cntGlobal <= to_unsigned(16#000#, 12);
      Deserializer1D_contl_cntInnerRegCtrol <= to_unsigned(16#800#, 12);
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' THEN
        Deserializer1D_contl_cnt <= Deserializer1D_contl_cnt_next;
        Deserializer1D_contl_cntGlobal <= Deserializer1D_contl_cntGlobal_next;
        Deserializer1D_contl_cntInnerRegCtrol <= Deserializer1D_contl_cntInnerRegCtrol_next;
      END IF;
    END IF;
  END PROCESS Deserializer1D_contl_process;

  Deserializer1D_contl_output : PROCESS (Deserializer1D_contl_cnt, Deserializer1D_contl_cntGlobal,
       Deserializer1D_contl_cntInnerRegCtrol, FFT_out2)
    VARIABLE out0 : std_logic;
    VARIABLE validOutput : std_logic;
    VARIABLE cntInnerRegCtrol_temp : unsigned(11 DOWNTO 0);
  BEGIN
    cntInnerRegCtrol_temp := Deserializer1D_contl_cntInnerRegCtrol;
    Deserializer1D_contl_cnt_next <= Deserializer1D_contl_cnt;
    Deserializer1D_tapDelayEn <= FFT_out2;
    Deserializer1D_hOutSignalsContl <= '0';
    out0 := '0';
    Deserializer1D_innerRegCtrolEn <= '0';
    validOutput := '0';
    IF (FFT_out2 /= '0') AND (Deserializer1D_contl_cnt = to_unsigned(16#7FF#, 12)) THEN 
      validOutput := '1';
    END IF;
    IF validOutput = '1' THEN 
      Deserializer1D_hOutSignalsContl <= '1';
      out0 := '1';
      Deserializer1D_innerRegCtrolEn <= '1';
      cntInnerRegCtrol_temp := Deserializer1D_contl_cntGlobal;
    END IF;
    IF ( NOT out0) = '1' AND (Deserializer1D_contl_cntGlobal = cntInnerRegCtrol_temp) THEN 
      Deserializer1D_innerRegCtrolEn <= '1';
      cntInnerRegCtrol_temp := to_unsigned(16#800#, 12);
    END IF;
    IF FFT_out2 /= '0' THEN 
      IF Deserializer1D_contl_cnt = to_unsigned(16#7FF#, 12) THEN 
        Deserializer1D_contl_cnt_next <= to_unsigned(16#000#, 12);
      ELSE 
        Deserializer1D_contl_cnt_next <= Deserializer1D_contl_cnt + to_unsigned(16#001#, 12);
      END IF;
    END IF;
    IF Deserializer1D_contl_cntGlobal = to_unsigned(16#7FF#, 12) THEN 
      Deserializer1D_contl_cntGlobal_next <= to_unsigned(16#000#, 12);
    ELSE 
      Deserializer1D_contl_cntGlobal_next <= Deserializer1D_contl_cntGlobal + to_unsigned(16#001#, 12);
    END IF;
    Deserializer1D_innerRegEn <= out0;
    IF Deserializer1D_contl_cntGlobal = to_unsigned(16#000#, 12) THEN 
      Deserializer1D_outBypassEn <= '1';
    ELSE 
      Deserializer1D_outBypassEn <= '0';
    END IF;
    Deserializer1D_contl_cntInnerRegCtrol_next <= cntInnerRegCtrol_temp;
  END PROCESS Deserializer1D_contl_output;


  Deserializer1D_tapDelayEn_1 <= enb_1_25_0 AND Deserializer1D_tapDelayEn;

  FFT_out1_re_signed <= signed(FFT_out1_re);

  FFT_out1_im_signed <= signed(FFT_out1_im);

  Bit_Shift_out1_re <= SHIFT_RIGHT(FFT_out1_re_signed, 11);
  Bit_Shift_out1_im <= SHIFT_RIGHT(FFT_out1_im_signed, 11);

  
  Data_Type_Conversion_out1_re <= "011111111111" WHEN (Bit_Shift_out1_re(22) = '0') AND (Bit_Shift_out1_re(21 DOWNTO 11) /= "00000000000") ELSE
      "100000000000" WHEN (Bit_Shift_out1_re(22) = '1') AND (Bit_Shift_out1_re(21 DOWNTO 11) /= "11111111111") ELSE
      Bit_Shift_out1_re(11 DOWNTO 0);
  
  Data_Type_Conversion_out1_im <= "011111111111" WHEN (Bit_Shift_out1_im(22) = '0') AND (Bit_Shift_out1_im(21 DOWNTO 11) /= "00000000000") ELSE
      "100000000000" WHEN (Bit_Shift_out1_im(22) = '1') AND (Bit_Shift_out1_im(21 DOWNTO 11) /= "11111111111") ELSE
      Bit_Shift_out1_im(11 DOWNTO 0);

  Deserializer1D_tapDelayComp_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_tapout_re <= (OTHERS => to_signed(16#000#, 12));
      Deserializer1D_tapout_im <= (OTHERS => to_signed(16#000#, 12));
